import {chromium} from 'playwright';import {mkdir,writeFile} from 'node:fs/promises';
const folder='diagnostics/home-ai-external-baseline-20261118';await mkdir(folder,{recursive:true});const browser=await chromium.launch({headless:true,executablePath:process.env.HB_BROWSER_PATH}),report={runUrl:'https://github.com/hossambahr229-star/hossambahr-site/actions/runs/'+process.env.GITHUB_RUN_ID,scope:'Real anonymous homepage assistant journey, synthetic public transaction only'};
try{const context=await browser.newContext({viewport:{width:1440,height:1000}}),page=await context.newPage(),requests=[];context.on('request',r=>{if(r.isNavigationRequest())requests.push(r.url());});await page.goto('https://hossambahr.com/',{waitUntil:'networkidle'});await page.locator('[data-premium-ai-open],[data-premium-ai-toggle]').filter({visible:true}).first().click();const input=page.locator('#premium-ai-panel textarea');await input.fill('تجديد رخصة تجارية في دبي');await input.press('Enter');const official=page.locator('#premium-ai-panel .hb-chat-actions a[href^="https://"]').first();await official.waitFor({state:'visible',timeout:100000});const href=await official.getAttribute('href');report.href=href;report.label=await official.innerText();report.urlBefore=page.url();await page.evaluate(()=>{window.hbClickObservations=[];document.addEventListener('click',e=>{const a=e.target.closest('a');if(a)queueMicrotask(()=>window.hbClickObservations.push({href:a.href,prevented:e.defaultPrevented}));});});const nav=context.waitForEvent('request',{predicate:r=>r.isNavigationRequest()&&r.url().startsWith(href),timeout:8000}).catch(()=>null);await official.click();const request=await nav;report.navigationRequested=Boolean(request);report.observed=await page.evaluate(()=>window.hbClickObservations);report.requests=requests;report.uiText=await page.locator('#premium-ai-panel').innerText();report.status=report.navigationRequested?'PASS':'FAIL';await page.screenshot({path:folder+'/desktop.jpg',type:'jpeg',quality:85});}catch(e){report.status='ERROR';report.error=String(e);}finally{await writeFile(folder+'/report.json',JSON.stringify(report,null,2));await browser.close();}console.log(JSON.stringify(report));